int n,A,B,C,u[N],v[N],w[N];
inline ull Rand(ull &k1, ull &k2){
	ull k3 = k1, k4 = k2;
	k1 = k4;
	k3 ^= (k3 << 23);
	k2 = k3 ^ k4 ^ (k3 >> 17) ^ (k4 >> 26);
	return k2 + k4;
