Rmq mex
看起来就非常莫队是吧。
然而，如何快速找出
\(mex\)
呢？
如果直接加一位一位的查找，复杂度肯定会炸。
有两种解决办法：
对着值域建一棵线段树，然后上二分。
对值域分块。
int n,m;
int a[N],block;
int pos[N];
int ans[N];
struct node{
    int l,r,id;
}q[N];
inline bool cmp(node x,node y){
	if(pos[x.l]!=pos[y.l])return pos[x.l]<pos[y.l];
	if(pos[x.l]&1)return x.r>y.r;
	return x.r<y.r;
}
int K=500;
int cnt[N],num[N];
inline void add(int x){
    if(!cnt[x])num[x/K]++;
    cnt[x]++;
}
inline void del(int x){
    if(cnt[x]==1)num[x/K]--;
    cnt[x]--;
}
inline void ask(int x){
    for(int i=1;i<=K;i++){
        if(num[i-1]!=K){
            for(int j=(i-1)*K;j<i*K;j++){
                if(!cnt[j]){
                    ans[q[x].id]=j;
                    return;
                }
            }
        }
    }
}
signed main(){
    n=read();m=read();
    block=sqrt(n);
    up(i,1,n){
        a[i]=read();
        pos[i]=(i-1)/block+1;
    }
    up(i,1,m){
        q[i].l=read();
        q[i].r=read();
        q[i].id=i;
    }
    sort(q+1,q+1+m,cmp);
    int l=q[1].l,r=q[1].r;
    for(int i=l;i<=r;i++)add(a[i]);
    ask(1);
    up(i,2,m){
        while(l<q[i].l)del(a[l++]);
        while(l>q[i].l)add(a[--l]);
        while(r<q[i].r)add(a[++r]);
        while(r>q[i].r)del(a[r--]);
