    if(pos<=mid)change(lc,l,mid,pos,v);
    else change(rc,mid+1,r,pos,v);
    maxl[k]=max(maxl[lc],maxl[rc]);
    ans[k]=ans[lc]+ask(rc,mid+1,r,maxl[lc]);
