int lim;
bool del[N];
inline int getsiz(int u,int from){
	if(del[u])return 0;
	int res=1;
	for(auto [v,w]:g[u]){
		if(v==from)continue;
		res+=getsiz(v,u);
	}
	return res;
}
inline int getwc(int u,int from,int tot,int&wc){
	if(del[u])return 0;
	int sum=1,maxl=0;
	for(auto [v,w]:g[u]){
		if(v==from)continue;
		int t=getwc(v,u,tot,wc);
		maxl=max(maxl,t);
		sum+=t;
	}
	maxl=max(maxl,tot-sum);
	if(maxl<=tot/2)wc=u;
	return sum;
}
inline void dfs(int u,int from,int dis,vector<int>&q){
	if(del[u])return;
	q.push_back(dis);
	for(auto [v,w]:g[u]){
		if(v==from)continue;
		dfs(v,u,dis+w,q);
	}
}
inline int get(vector<int>&a){
	sort(a.begin(),a.end());
	int res=0,len=a.size();
	for(int i=len-1,j=-1;i>=0;i--){
		while(j+1<i&&a[j+1]+a[i]<=lim)j++;
		j=min(j,i-1);
		res+=j+1;
	}
	return res;
}
inline int clac(int u){
	if(del[u])return 0;
	int res=0;
	getwc(u,0,getsiz(u,0),u);
	del[u]=1;
	vector<int>p;
	for(auto [v,w]:g[u]){
		if(del[v])continue;
		vector<int>q;
		dfs(v,u,w,q);
		res-=get(q);
		for(auto x:q){
			p.push_back(x);
			if(x<=lim)res++;
		} 
	}
	res+=get(p);
	for(auto [v,w]:g[u])res+=clac(v);
	return res;
}
