        while(pos!=1){//不停的升到父亲节点，如果该点是右儿子，那么查找左儿子，反之亦然
            pos/=2;w--;
            if(w<0)break;
            if(pre==pos*2)upp+=clac(w,pos);
            else if(pre==pos*2+1)upp+=clac2(w,pos);
            pre=pos;
        }
        int l=x,r=x;
        if(k>=62){
            down=0;
            goto F;
        }
        up(i,1,k){
            l=l*2;
            r=r*2+1;
        }
        if(r<=n)down=(r-l+1);
        else if(l>n)down=0;
        else down=n-l+1;
        F:;
        write(upp+down,1);    
    }
    return 0;
}

\(T1\)
sbsbsbsbsbsbsbsbsbsbsb。
最难的一道题。
因为边的权值小于
\(30\)
。
所以可以暴力枚举最大的边权。
然后让这条边的次数尽可能的多。
把联通块分成多个，使得匹配最多。
另
\(x=\max \{a_i\},s=\sum a_i\)
如果
\(x\times 2>s\)
，有
\(s-x\)
个匹配。
否则,有
\(s/2\)
个匹配。
那么就一次一次删点就完了。
