    dn(k,30,0){
        memset(vis,0,sizeof vis);
        cnt=0;lim=k-1;
        up(i,1,n){
            if(!del[i]&&!vis[i]){
                cnt++;
                p[cnt].clear();
                dfs(i);
            }
        }
        int maxl=0,pos=0,tot=0;
		up(i,1,cnt){
			int u=p[i].size();
			if(u>maxl){
				maxl=u;
                pos=i;
