vector<pii>fac;
inline void devide(int x){
    int t=x;
    for(int i=2;i<=sqrt(x);i++){
        if(t%i==0){
            int res=0;
            while(t%i==0){
                t/=i;
                res++;
            }   
            fac.push_back({i,res});
        }
    }
    if(t!=1)fac.push_back({t,1});
}
