    }
    if(R/Q==L/Q){
        devide(L/Q*Q);
        int res=1;
        for(auto [a,b]:fac){
            res=res*(b+1);
        }
        cout<<res<<endl;
        return 0;
    }
    else{
        devide(Q);
        int res=1;
        for(auto [a,b]:fac){
            res=res*(b+1);
        }
        cout<<res<<endl;
        return 0;
    }
    return 0;
}
