        g[u].push_back(v);
        //g[v].push_back(u);
        deg[v]++;
        fa[find(u)]=find(v);
    }
    int ans=n;
    up(i,1,n){
        if(fa[i]==i){
            ans--;
            vis[i]=1;
        }
    }
    up(i,1,n)if(!deg[i])q.push(i);
    while(q.size()){
        int u=q.front();q.pop();
        for(auto v:g[u]){
            if(!--deg[v])q.push(v);
        }
    }
    up(i,1,n){
        if(deg[i]){
            ans+=vis[find(i)],vis[find(i)]=0;
        }
    }
