Population Size
有一个非常显然的贪心，一个数如果能够放在前一个等差数列里，那么就要放在那个等差数列里。
大体的思路有了，然后是一些细节，比如所有的数都是正整数，所以要判断那个数列会不会小于
\(0\)
。
int n,m;
int a[N];
signed main(){
	ios_base::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n;
    up(i,1,n)cin>>a[i];
    int u=1,ans=0;
    while(u<=n){
        ans++;
        int d,sx=0,mx=0,nxt=0;
        up(i,u,n){
            if(a[i]==-1)continue;
            if(sx==0)sx=i;
            else{
                nxt=i;
                break;
            }
        }
        if(nxt==0)break;
        if((a[nxt]-a[sx])%(nxt-sx)!=0){
            u=nxt; 
            continue;
        }
        d=(a[nxt]-a[sx])/(nxt-sx);
        if(a[sx]-(sx-u)*d<=0){
            u=nxt;
            continue;
        }
        int last=a[nxt];
		u=nxt+1;
		while(u<=n){
			if(last+d<=0)break;
			if(a[u]==-1||a[u]==last+d)last+=d;
			else break;
			++u;
		}
    }
    cout<<ans;
    return 0;
}

