char a[55][55];
int dp[40][1<<20],n;
bool vis[40][1<<20];
inline int dfs(int step,int st){
	if(vis[step][st])return dp[step][st];
	int&res=dp[step][st];
	vis[step][st]=1;
	if(step==n*2-2)res=0;
	else{
		if(step&1)res=-inf;
		else res=inf;
		int mask[30];
		memset(mask,0,sizeof mask);
		int cnt=0;
		for(int j=0;j<=step+1;j++){
			int x=step+1-j;
			int y=j;
			if(x>=n||y>=n)continue;
			mask[a[x][y]-'a']|=(1<<cnt);
			cnt++;
		}
		up(i,0,25){
			if(mask[i]){
				int x;
				if(step+1<n)x=(st|(st<<1))&mask[i];
				else x=(st|(st>>1))&mask[i];
				if(x==0)continue;
				int tmp=0;
				if(i==0)tmp=1;
				else if(i==1)tmp=-1;
				if(step&1)res=max(res,tmp+dfs(step+1,x));
				else res=min(res,tmp+dfs(step+1,x));
			}
		}
	}
	if(step==0){
		if(a[0][0]=='a')res++;
		else if(a[0][0]=='b')res--;
	}
	return res;

}

