inline int get_phi(int x){
	int res=x,tmp=x;
	if(x==1)return 1;
	for(int i = 2; i * i<=x; i ++) {
		if(tmp % i == 0) {
			res = res / i * (i - 1);
			while(tmp % i == 0) tmp /= i;
		}
	}
	if(tmp > 1) res = res / tmp * (tmp - 1);
	return res;
}
