一个
\(O(nk)\)
复杂度的暴力DP是很容易想的。
然而正解却是贪心。
当
\(k=1\)
时，显然是取最大的
\(a[i]\)
。
当
\(k=2\)
时，要么取
\(a[i]\)
和
\(\max_{j<(i-1)||j>(i+1)}(a[j])\)
，要么取
\(a[i-1],a[i+1]\)
。
那么我们可以考率，当从优先队列取出了一个点后，我们再往里面加一个点，权值为
\(a[i+1]+a[i-1]-a[i]\)
。
int n,k;
pii t;
bool vis[N];
int a[N],l[N],r[N],ans;
priority_queue<pii>q;
signed main(){
	n=read();k=read();
	up(i,1,n){
		a[i]=read();
		q.push({a[i],i});
		l[i]=i-1;r[i]=i+1;
	}
	l[n+1]=n;r[0]=1;
	up(i,1,k){
		while(vis[q.top().second])q.pop();
		t=q.top(); q.pop();
		if(t.first<0) break;
		ans+=t.first;
		int pos=t.second;
		a[pos]=a[l[pos]]+a[r[pos]]-a[pos];
		t.first=a[pos]; 
		vis[l[pos]]=vis[r[pos]]=1;
		l[pos]=l[l[pos]];
		r[pos]=r[r[pos]];
		r[l[pos]]=pos;
		l[r[pos]]=pos; 
		q.push(t);
	}
	cout<<ans;
	return 0;
}
