inline void exgcd(int a,int b,int& d,int& x,int& y){
	int t;
	if(b==0){d=a;x=1;y=0;}
	else{
		exgcd(b,a%b,d,x,y);
		t=x;x=y;y=t-(a/b)*y;
	}
}
