		int u,v,cap,flow,cost;
	};
	vector<edge>edges;
	vector<int>g[N];
	int a[N],p[N];
	int vis[N];
	int dis[N];
	inline void add(int u,int v,int cap,int cost){
		edges.push_back({u,v,cap,0,cost});
		edges.push_back({v,u,0,0,-cost});
		int t=edges.size();
		g[u].push_back(t-2);
		g[v].push_back(t-1);
	}
	inline int maxflow(int s,int t){
		int flow=0;
		for(;;){
			up(i,1,n)a[i]=0;
			queue<int>q;
			q.push(s);
			a[s]=inf;
			while(q.size()){
				int u=q.front();q.pop();
				for(auto i:g[u]){
					auto e=edges[i];
					if(!a[e.v]&&e.cap>e.flow){
						p[e.v]=i;
						a[e.v]=min(a[u],e.cap-e.flow);
						q.push(e.v);
					}
				}
				if(a[t])break;
			}
			if(!a[t])break;
			for(int u=t;u!=s;u=edges[p[u]].u){
				edges[p[u]].flow+=a[t];
				edges[p[u]^1].flow-=a[t];
			}
			flow+=a[t];
		}
		return flow;
	}
	inline bool spfa(int s,int t,int &flow,int &cost){
		memset(dis,0x3f,sizeof dis);
		memset(vis,0,sizeof vis);
		memset(a,0,sizeof a);
		dis[s]=0;vis[s]=1;
		p[s]=0;a[s]=inf;
		queue<int>q;
		q.push(s);
		while(q.size()){
			int u=q.front();q.pop();
			vis[u]=0;
			for(auto i:g[u]){
				auto e=edges[i];
				if(e.cap>e.flow&&dis[e.v]>dis[u]+e.cost){
					dis[e.v]=dis[u]+e.cost;
					p[e.v]=i;
					a[e.v]=min(a[u],e.cap-e.flow);
					if(!vis[e.v]){
						q.push(e.v);
						vis[e.v]=1;
					}
				}
			}
		}
		if(dis[t]>=inf)return 0;
		flow+=a[t];
		cost+=dis[t]*a[t];
		for(int u=t;u!=s;u=edges[p[u]].u){
			edges[p[u]].flow+=a[t];
			edges[p[u]^1].flow-=a[t];
		}
		return 1;
	}
	inline int mincostmaxflow(int s,int t,int& cost){
		int flow=0;
		cost=0;
		while(spfa(s,t,flow,cost));
		return flow;
	}
}E;
