inline int ksm(int a,int b){
    int res=1;
    while(b){
        if(b&1)res=res*a%mod;
        a=a*a%mod;
        b>>=1;
    }
    return res;
}
int inv[N],fac[N];
inline void init(){
    inv[0]=fac[0]=1;
    up(i,1,mod+10){
        fac[i]=fac[i-1]*i%mod;
        inv[i]=ksm(fac[i],mod-2);
    }
}
inline int C(int n,int m){
	if(n<m) return 0;
	return fac[n]*inv[m]%mod*inv[n-m]%mod;
}
inline int lucas(int n,int m){
	if(m==0) return 1;
	return (C(n%mod,m%mod)*lucas(n/mod,m/mod))%mod;
}
