		for(int r=1,c=1;c<=n;c++,r++){
			int t=r;
			up(i,r+1,n){
				if(fabs(a[i][c])>fabs(a[t][c]))t=i;
			}
			up(i,c,n+1)swap(a[t][i],a[r][i]);
			if(!a[c][c]){
