inline void tarjan(int u){
    dfn[u]=low[u]=++tot;
    int son=0;
    for(auto v:g[u]){
        if(!dfn[v]){
            fa[v]=u;
            tarjan(v);
            low[u]=min(low[u],low[v]);
            if(low[v]>=dfn[u]){
                if(fa[u])flag=1;
                else son++;
            }
        }
        else if(v!=fa[u])low[u]=min(low[u],dfn[v]);
    }
    if(son>1)flag=1;
}
