namespace DSU{
    int fa[N], siz[N];
    void init(int n) {
        up(i,1,n) fa[i] = i, siz[i] = 1;
    }
    int find(int x) {
        return fa[x] == x ? fa[x] : fa[x] = find(fa[x]);
    }
    void unionn(int x, int y) {
        int fx = find(x), fy = find(y);
		if(fx==fy)return;
        if(siz[fx] > siz[fy]) swap(fx, fy);
        fa[fx] = fy; siz[fy] += siz[fx];
    }
}using namespace DSU;

