inline void dfs(int l,int r){
    if (l==r) return;
    int mid=(l+r)>>1,t0=l,t1=r;
    up(i,l,mid)if(a[t0]>a[i]) t0=i;
    dn(i,r,mid+1)if(b[t1]>b[i])t1=i;
    up(i,l,mid)e[++m]={i,t1,a[i]+b[t1]};
	dn(i,r,mid+1)e[++m]={t0,i,a[t0]+b[i]};
    dfs(l,mid);
	dfs(mid+1,r);
}
signed main(){
