        a[i]=x-i*D,b[i]=x+i*D;
    }
    dfs(1,n);
	sort(e+1,e+1+m,cmp);
    up(i,1,m){
		int fx=find(e[i].x),fy=find(e[i].y);
        if (fx!=fy) {
			fa[fx]=fy;
			ans+=e[i].w;
		}
	}
	write(ans,1);
    return 0;
}
