struct FHQTreap{
    int cnt=0,root=0;
    struct node{
        int ls,rs;
        int key,pri;
        int siz,num;
        int sum,sum2;
    }tr[N];
    int ans;
    inline void build(int x,int num){
        cnt++;
        tr[cnt].siz=num;
        tr[cnt].num=num;
        tr[cnt].ls=tr[cnt].rs=0;
        tr[cnt].sum=x*num;
        tr[cnt].sum2=x*num;
        tr[cnt].key=x;
        tr[cnt].pri=rand();
    }
    inline void push_up(int k){
        tr[k].siz=tr[tr[k].ls].siz+tr[tr[k].rs].siz+tr[k].num;
        tr[k].sum=tr[tr[k].ls].sum+tr[tr[k].rs].sum+tr[k].sum2;
    }
    inline void split(int u,int x,int &l,int &r){
        if(u==0){l=r=0;return;}
        if(tr[u].key<=x){
            l=u;
            split(tr[u].rs,x,tr[u].rs,r);
        }
        else{
            r=u;
            split(tr[u].ls,x,l,tr[u].ls);
        }
        push_up(u);
    }
    inline int merge(int l,int r){
        if(!l||!r)return l|r;
        if(tr[l].pri>tr[r].pri){
            tr[l].rs=merge(tr[l].rs,r);
            push_up(l);
            return l;
        }
        else{
            tr[r].ls=merge(l,tr[r].ls);
            push_up(r);
            return r;
        }
    }
    inline void insert(int x,int nums){
    	int l,r,p;
        split(root,x,l,r);
        split(l,x-1,l,p);
        if(tr[p].num==0){
			build(x,nums);
			p=cnt; 
		} 
		else{
			tr[p].num+=nums;
			tr[p].siz+=nums;
			tr[p].sum+=nums*tr[p].key;
			tr[p].sum2+=nums*tr[p].key;
		}
        root=merge(merge(l,p),r);
	}
    inline void del(int x,int nums){
        int l,r,p;
        split(root,x,l,r);
        split(l,x-1,l,p);
        tr[p].siz-=nums;
        tr[p].num-=nums;
        tr[p].sum-=tr[p].key*nums;
        tr[p].sum2-=tr[p].key*nums;
        if(tr[p].num==0)root=merge(l,r);
        else root=merge(merge(l,p),r);
    }
    inline int kth(int u,int k){
    	if(k<=tr[tr[u].ls].siz)return kth(tr[u].ls,k);
        else if(k<=tr[tr[u].ls].siz+tr[u].num)return u;
        else return kth(tr[u].rs,k-tr[tr[u].ls].siz-tr[u].num);
    }
    inline int size(int rt){
        return tr[rt].siz;
    }
	inline int anskth(int k){
		return tr[kth(root,k)].key;
	}
