struct FHQTreap{
	struct node{
		int ls,rs;
		int key,pri;
		int size;
		i128 sum;
	}tr[N];
	int root,cnt;
	inline void build(int x){
		cnt++;
		tr[cnt].ls=tr[cnt].rs=0;
		tr[cnt].key=x;
		tr[cnt].sum=x;
		tr[cnt].pri=rand();
		tr[cnt].size=1;
	}
	inline void push_up(int u){
		tr[u].size=tr[tr[u].ls].size+tr[tr[u].rs].size+1;
		tr[u].sum=tr[tr[u].ls].sum+tr[tr[u].rs].sum+tr[u].key;
	}
	inline void split(int u,int x,int &l,int &r){
		if(!u){l=r=0;return;}
		if(tr[u].key<=x){
			l=u;
			split(tr[u].rs,x,tr[u].rs,r);
		}
		else{
			r=u;
			split(tr[u].ls,x,l,tr[u].ls);
		}
		push_up(u);
	}
	inline int merge(int l,int r){
		if(!l||!r)return l|r;
		if(tr[l].pri>tr[r].pri){
			tr[l].rs=merge(tr[l].rs,r);
			push_up(l);
			return l;
		}
		else{
			tr[r].ls=merge(l,tr[r].ls);
			push_up(r);
			return r;
		}
	}
	inline void insert(int x){
		int l,r;
		split(root,x,l,r);
		build(x);
		root=merge(merge(l,cnt),r);
	}
	inline void del(int x){
		int l,r,p;
		split(root,x,l,r);
		split(l,x-1,l,p);
		p=merge(tr[p].ls,tr[p].rs);
		root=merge(merge(l,p),r);
	}
	inline i128 solve(int x){
		int l,r;
		i128 t=0;
		split(root,x,l,r);
		t+=tr[l].size*x-tr[l].sum;
		t+=tr[r].sum-x*tr[r].size;
		root=merge(l,r);
		return t;
	}
}fx,fy;
