signed main(){
	n=read();q=read();base=read();
	int x,y;
	up(i,1,n){
		int x=read(),y=read();
		a[i].qx=(x+y);a[i].qy=(x-y);
		fx.insert(a[i].qx);
		fy.insert(a[i].qy);
	} 
	int op,a1,a2,b1,b2,num,qx,qy;
	while(q--){
		i128 ans=0;
		op=read();
		if(op==1){
			a1=read()%base;b1=read()%base;a2=read()%base;b2=read()%base;
			x=(a1*T+b1)%base;
			y=(a2*T+b2)%base;
			qx=(x+y);qy=(x-y);
			ans+=fx.solve(qx);
			ans+=fy.solve(qy);
			ans+=2*(n-1);
			write(ans,1);
			ans%=base;
			T=ans;
		}
		else{
			num=read();a1=read();b1=read();a2=read();b2=read();
			x=(a1*T+b1)%base;
			y=(a2*T+b2)%base;
			qx=(x+y);qy=(x-y);
			fx.del(a[num].qx);fy.del(a[num].qy);
			fx.insert(qx);fy.insert(qy);
			a[num].qx=qx;a[num].qy=qy;
		}
	}
	return 0;
}
\(T5\)
一个非常显然的事实：一个点双对答案的贡献必然是点双里面的最小权值
建立圆方树，方点的权值为点双中的最小圆点权值。
然后原图就变成了一棵树，询问时就可以直接树剖套线段树求路径最小值了.
对于一个方点，
\(multiset\)
里面存它所有子节点的权值。
然后修改一个圆点时，就只需要动它父亲的multiset（它的父亲必然是一个方点）。
询问时，仍然可以正常询问，只不过如果lca是一个方点，那还要额外计算fa[lca]的权值对答案的贡献
