inline void push_up(int k){
	tr[k].minl=min(tr[k<<1].minl,tr[k<<1|1].minl);
}
inline void build(int k,int l,int r){
	tr[k].l=l;tr[k].r=r;
	if(l==r){
		tr[k].minl=dis[a[l]];
		return ;
	}
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	push_up(k);
}
inline void update(int k,int x,int val){
	if(tr[k].l==tr[k].r){
		tr[k].minl=val;
		return ;
	}
	int mid=(tr[k].l+tr[k].r)>>1;
	if(x<=mid)update(k<<1,x,val);
	else update(k<<1|1,x,val);
	push_up(k);
}
inline int query(int k,int x,int y){
	if(x<=tr[k].l&&tr[k].r<=y)return tr[k].minl;
	int mid=(tr[k].l+tr[k].r)>>1,ret=0x3f3f3f3f;
	if(x<=mid)ret=min(ret,query(k<<1,x,y));
	if(mid<y)ret=min(ret,query(k<<1|1,x,y));
	return ret;
}
int querypath(int x,int y){
	int ret=0x3f3f3f3f;
	while(top[x]!=top[y]){
		if(dep[top[x]]<dep[top[y]])swap(x,y);
		ret=min(ret,query(1,id[top[x]],id[x]));
		x=f[top[x]];
	}
	if(dep[x]>dep[y])swap(x,y);
	ret=min(ret,query(1,id[x],id[y]));
	if(x>n)ret=min(ret,dis[f[x]]);
	return ret;
}
