inline void build(int k,int l,int r){
	if(l==r){
		a[l]=k;
		return;
	}
	int mid=(l+r)>>1;
	g[k].push_back({ls,0});
	g[k].push_back({rs,0});
	g[N+(ls)].push_back({k+N,0});
	g[N+(rs)].push_back({k+N,0});
	build(ls,l,mid);
	build(rs,mid+1,r);
}
inline void add(int k,int l,int r,int x,int y,int u,int w,int op){
