		if(op==3)g[k+N].push_back({u,w});
		return;
	}
	int mid=(l+r)>>1;
	if(mid>=x)add(ls,l,mid,x,y,u,w,op);
	if(mid<y)add(rs,mid+1,r,x,y,u,w,op);
}
