一种优雅的暴力——分块
众所周知，线段树是将一个数组放在二叉树上，每次查询，修改的复杂度是
\(logn\)
,空间复杂度是
\(4N\)
。而分块则是一种
\(O(n\sqrt n )\)
,空间
\(O(n)\)
的算法。由于常熟极小，在1e5的范围内跑的比线段树快多了。
给出线段树1的分块代码。
code
#include<bits/stdc++.h>

using namespace std;

#define int long long

const int mod=1e8;

inline int read(){
	int u=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if(ch=='-') f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){u=u*10+ch-48;ch=getchar();}
	return u*f;
}
int n,m;
int st[50050],ed[50050],pos[500500],sum[50050],add[50050],a[500500];
void init(){
	int block=sqrt(n);
	int t=n/block;
	if(n%block)t++;
	for(int i=1;i<=t;i++){
		st[i]=(i-1)*block+1;
		ed[i]=i*block;
	}
	ed[t]=n;
	for(int i=1;i<=n;i++){
		pos[i]=(i-1)/block+1;
	}
	for(int i=1;i<=t;i++){
		for(int j=st[i];j<=ed[i];j++){
			sum[i]+=a[j];
		}
	}
}
void change(int l,int r,int d){
	int p=pos[l],q=pos[r];
	if(p==q){
		for(int i=l;i<=r;i++)a[i]+=d;
		sum[p]+=d*(r-l+1);
	}
	else{
		for(int i=p+1;i<=q-1;i++)add[i]+=d;
		for(int i=l;i<=ed[p];i++)a[i]+=d;
		sum[p]+=d*(ed[p]-l+1);
		for(int i=st[q];i<=r;i++)a[i]+=d;
		sum[q]+=d*(r-st[q]+1);
	}
}
inline int ask(int l,int r){
	int p=pos[l],q=pos[r];
	int ans=0;
	if(p==q){
		for(int i=l;i<=r;i++)ans+=a[i];
		ans+=add[p]*(r-l+1);
	}
	else{
		for(int i=p+1;i<=q-1;i++)ans+=sum[i]+add[i]*(ed[i]-st[i]+1);
		for(int i=l;i<=ed[p];i++)ans+=a[i];
		ans+=add[p]*(ed[p]-l+1);
		for(int i=st[q];i<=r;i++)ans+=a[i];
		ans+=add[q]*(r-st[q]+1);
	}
	return ans;
}
signed main(){
	n=read();m=read();
	for(int i=1;i<=n;i++)a[i]=read();
	init();
	int op,l,r,k;
	while(m--){
		op=read();
		if(op==1){
			l=read();r=read();k=read();
			change(l,r,k);
		}
		if(op==2){
			l=read();r=read();
			printf("%lld\n",ask(l,r));
		}
	}
    return 0;
}
