struct FHQTreap{
    int cnt=0,root=0;
    struct node{
        int ls,rs;
        int key,pri;
        int siz;
    }tr[N];
    int ans;
    inline void build(int x){
        cnt++;
        tr[cnt].siz=1;
        tr[cnt].ls=tr[cnt].rs=0;
        tr[cnt].key=x;
        tr[cnt].pri=rand();
    }
    inline void push_up(int k){
        tr[k].siz=tr[tr[k].ls].siz+tr[tr[k].rs].siz+1;
    }
    inline void split(int u,int x,int &l,int &r){
        if(u==0){l=r=0;return;}
        if(tr[u].key<=x){
            l=u;
            split(tr[u].rs,x,tr[u].rs,r);
        }
        else{
            r=u;
            split(tr[u].ls,x,l,tr[u].ls);
        }
        push_up(u);
    }
    inline int merge(int l,int r){
        if(l==0||r==0)return l+r;
        if(tr[l].pri>tr[r].pri){
            tr[l].rs=merge(tr[l].rs,r);
            push_up(l);
            return l;
        }
        else{
            tr[r].ls=merge(l,tr[r].ls);
            push_up(r);
            return r;
        }
    }
    inline void insert(int x){
        int l,r;
        split(root,x,l,r);
        build(x);
        root=merge(merge(l,cnt),r);
    }
    inline void del(int x){
        int l,r,p;
        split(root,x,l,r);
        split(l,x-1,l,p);
        p=merge(tr[p].ls,tr[p].rs);
        root=merge(merge(l,p),r);
    }
    inline void getrank(int x){
        int l,r;
        split(root,x-1,l,r);
        int last=tr[l].siz+1;
        root=merge(l,r);
    } 
