        if(k==tr[tr[u].ls].siz+1)return u;
        if(k<=tr[tr[u].ls].siz)return kth(tr[u].ls,k);
        else return kth(tr[u].rs,k-tr[tr[u].ls].siz-1);
    }
    inline int getpre(int x){
        int l,r;
        split(root,x-1,l,r);
        int last=tr[kth(l,tr[l].siz)].key;
        root=merge(l,r);
        return last;
    }
