        else L=u,split(tr[u].rs,x-tr[tr[u].ls].siz-1,tr[u].rs,R);
        push_up(u);
    }
    inline int merge(int L,int R){
        if(!L||!R)return L|R;
        push_down(L);
        push_down(R);
        if(tr[L].key>tr[R].key){
            tr[L].rs=merge(tr[L].rs,R);
            push_up(L);
            return L;
        }
        else{
            tr[R].ls=merge(L,tr[R].ls);
            push_up(R);
            return R;
        }
