        int mid=(r+l)/2;
        double ret=0;
        if (mid>=L)
            ret+=query_b(rt<<1,l,mid,L,R);
        if (mid<R)
            ret+=query_b(rt<<1|1,mid+1,r,L,R);
        return ret;
    }
}
void update(int rt,int l,int r,int L,int R,double x)
{
    if (l>=L && r<=R)
        mark[rt]+=x,segb[rt]+=2*x*sega[rt]+x*x*(r-l+1),sega[rt]+=(r-l+1)*x;
    else
