题目
思路：按行分治，再按列分治，交次进行；
\(up[0][k]\)
表示在
\(mid\)
上方，满足矩形
\(sum(i,j,up[0][i],mid)
的最小纵（横）坐标，
\(up[1][k]\)
为最大纵(横）坐标，答案可化为：
\($ans=\sum_{i=0}^{k}(up[0][i]-up[0][i+1])*(up[1][k-i+1]-up[1][k-i])\)
$
#include <bits/stdc++.h>
using namespace std;
//#define int long long 
inline int read(){
	int x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=x*10+ch-48;ch=getchar();}
	return x*f;
