int dp(int n){
	if(!n)return 0;
	vector<int>nums;
	while(n)nums.push_back(n%b),n/=b;//把n转化为b进制
	int res=0;
	int last=0;//记录上一个x
	for(int i=nums.size()-1;i>=0;i--){
		int x=nums[i];
		if(x){
			res+=f[i][k-last];
			if(x>1){
				if(k-last-1>=0)res+=f[i][k-last-1];
				break;
			}
			else{
				last++;
				if(last>k)break;
			}
		}
		if(!i&&last==k)res++;	
	}
	return res;
}
