		tr[k].sum=x*(tr[k].r-tr[k].l+1)%mod;
		return;
	}
	push_down(k);
	int mid=(tr[k].l+tr[k].r)>>1;
	if(l<=mid) change(k<<1,l,r,x);
	if(r>mid) change(k<<1|1,l,r,x);
