}
inline int ask(int k,int l,int r){
	if(l<=tr[k].l&&tr[k].r<=r){
		return tr[k].sum;
	}
	int res=0;
	int mid=(tr[k].l+tr[k].r)>>1;
	push_down(k);
	if(l<=mid) res=(res+ask(k<<1,l,r))%mod;
	if(mid<r)res=(res+ask(k<<1|1,l,r))%mod;
	return res;
}
int ksm(int a,int p){
	int rel=1;
	while(p){
		if(p%2==1)rel=(rel*a)%mod;
		a=(a*a)%mod;
		p>>=1;
	}
	return rel%mod;
}
